CREATE DATABASE IF NOT EXISTS stainless_laundry CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE stainless_laundry;
CREATE TABLE users (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, phone VARCHAR(20) NOT NULL, password_hash VARCHAR(255) NOT NULL, role ENUM('customer','admin','staff') NOT NULL DEFAULT 'customer', is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, INDEX(role));
CREATE TABLE customer_profiles (user_id INT UNSIGNED PRIMARY KEY, location VARCHAR(160) NOT NULL, address_details VARCHAR(255) NULL, CONSTRAINT fk_profile_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE services (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, description TEXT NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE service_options (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, service_id INT UNSIGNED NOT NULL, option_name VARCHAR(120) NOT NULL, unit_price DECIMAL(10,2) NOT NULL, is_active TINYINT(1) NOT NULL DEFAULT 1, FOREIGN KEY(service_id) REFERENCES services(id), INDEX(service_id,is_active));
CREATE TABLE orders (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, reference VARCHAR(30) NOT NULL UNIQUE, customer_id INT UNSIGNED NOT NULL, status VARCHAR(60) NOT NULL DEFAULT 'Order Placed', pickup_date DATE NOT NULL, pickup_time VARCHAR(40) NOT NULL, phone VARCHAR(20) NOT NULL, pickup_location VARCHAR(255) NOT NULL, delivery_location VARCHAR(255) NOT NULL, instructions TEXT NULL, payment_method ENUM('M-Pesa','Cash','Bank') NOT NULL DEFAULT 'Cash', subtotal DECIMAL(10,2) NOT NULL, pickup_fee DECIMAL(10,2) NOT NULL DEFAULT 0, total_amount DECIMAL(10,2) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(customer_id) REFERENCES users(id), INDEX(customer_id,status), INDEX(pickup_date));
CREATE TABLE order_items (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, service_option_id INT UNSIGNED NOT NULL, item_name VARCHAR(120) NOT NULL, size_name VARCHAR(120) NOT NULL, quantity INT UNSIGNED NOT NULL, unit_price DECIMAL(10,2) NOT NULL, subtotal DECIMAL(10,2) NOT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(service_option_id) REFERENCES service_options(id));
CREATE TABLE order_status_history (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, status VARCHAR(60) NOT NULL, notes TEXT NULL, updated_by INT UNSIGNED NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE, FOREIGN KEY(updated_by) REFERENCES users(id) ON DELETE SET NULL, INDEX(order_id,created_at));
CREATE TABLE pickups (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE, scheduled_at DATETIME NOT NULL, collected_at DATETIME NULL, assigned_to INT UNSIGNED NULL, internal_notes TEXT NULL, customer_notes TEXT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE deliveries (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL UNIQUE, scheduled_at DATETIME NULL, delivered_at DATETIME NULL, assigned_to INT UNSIGNED NULL, internal_notes TEXT NULL, customer_notes TEXT NULL, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE);
CREATE TABLE payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, order_id BIGINT UNSIGNED NOT NULL, amount DECIMAL(10,2) NOT NULL, method ENUM('M-Pesa','Cash','Bank') NOT NULL, reference VARCHAR(100) NULL, status ENUM('Unpaid','Partially Paid','Paid','Refunded') NOT NULL DEFAULT 'Paid', paid_at DATETIME NULL, recorded_by INT UNSIGNED NULL, FOREIGN KEY(order_id) REFERENCES orders(id), FOREIGN KEY(recorded_by) REFERENCES users(id) ON DELETE SET NULL, UNIQUE(order_id,reference));
CREATE TABLE notifications (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, order_id BIGINT UNSIGNED NULL, title VARCHAR(160) NOT NULL, message TEXT NOT NULL, read_at DATETIME NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE SET NULL, INDEX(user_id,read_at));
CREATE TABLE contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL, phone VARCHAR(20) NULL, message TEXT NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE password_resets (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NOT NULL, token_hash CHAR(64) NOT NULL, expires_at DATETIME NOT NULL, used_at DATETIME NULL, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE settings (setting_key VARCHAR(80) PRIMARY KEY, setting_value VARCHAR(255) NOT NULL);
CREATE TABLE audit_logs (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, user_id INT UNSIGNED NULL, action VARCHAR(160) NOT NULL, entity_type VARCHAR(60) NULL, entity_id BIGINT UNSIGNED NULL, details TEXT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
